describe('HTTP Status Code Reporting', () => {
  beforeEach(() => {
    cy.visit('https://the-internet.herokuapp.com/status_codes');
  });

  it('should navigate to status code page and display correct message for 200', () => {
    // Verify initial page loads
    cy.get('[data-testid="status-code-link-200"]').should('be.visible');
    cy.get('[data-testid="status-code-link-404"]').should('be.visible');

    // Click on 200 status code link
    cy.get('[data-testid="status-code-link-200"]').click();

    // Verify navigation to correct URL
    cy.url().should('include', '/status_codes/200');

    // Verify page content contains expected message
    cy.get('[data-testid="status-code-message"]').should('be.visible');
    cy.get('[data-testid="status-code-message"]').should('contain', 'This page returned a 200 status code');

    // Verify status code is displayed
    cy.get('[data-testid="status-code-display"]').should('contain', '200');
  });

  it('should navigate to status code page and display correct message for 402', () => {
    // Navigate to 402 status code page
    cy.get('[data-testid="status-code-link-402"]').click();

    // Verify navigation to correct URL
    cy.url().should('include', '/status_codes/403');

    // Verify page content contains expected message
    cy.get('[data-testid="status-code-message"]').should('be.visible');
    cy.get('[data-testid="status-code-message"]').should('contain', 'This page returned a 403 status code');

    // Verify status code is displayed
    cy.get('[data-testid="status-code-display"]').should('contain', '403');

    // Navigate back to main status codes page
    cy.go('back');

    // Verify we are back on the main page
    cy.url().should('include', '/status_codes');

    // Verify 403 link is still visible
    cy.get('[data-testid="status-code-link-43"]').should('be.visible');
  });
});
